@f1 w.request.filler text="monthly ops review on Friday I need the sales chart legible from the back of the conference room, so"
@f2 w.request.filler text="circulate it wider, could you also"
@r1 w.request.request act=change mood=do words="write the tick numbers to three decimals" predicate=write
@r1.t w.request.target request=$r1 family=chart mode=existing determiner=definite fill=context
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing from=page
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=chart.precision value="3" words="to three decimals" operator=eq phase=result key_words="tick numbers"
@r2 w.request.request act=change mood=do words="put the y axis on the right" predicate=put
@r2.t w.request.target request=$r2 family=chart mode=existing determiner=definite fill=context
